solution.javascript:
function findItinerary(tickets) {
  const graph = {};
  for (const [from, to] of tickets) { if (!graph[from]) graph[from] = []; graph[from].push(to); }
  for (const k in graph) graph[k].sort().reverse();
  const result = [];
  function dfs(node) {
    while (graph[node]?.length) dfs(graph[node].pop());
    result.push(node);
  }
  dfs('JFK');
  return result.reverse();
}

solution.cpp:
vector<string> findItinerary(vector<vector<string>>& tickets) {
    unordered_map<string, vector<string>> graph;
    for (auto& t : tickets) graph[t[0]].push_back(t[1]);
    for (auto& [k, v] : graph) sort(v.rbegin(), v.rend());
    vector<string> result;
    function<void(string)> dfs = [&](string node) {
        while (!graph[node].empty()) { string next = graph[node].back(); graph[node].pop_back(); dfs(next); }
        result.push_back(node);
    };
    dfs("JFK");
    reverse(result.begin(), result.end());
    return result;
}
